import { ACCOUNT_LIMITS } from './account.constants';

export interface RoundResult {
  bid: number;
  tricksWon: number;
  roundScore: number;
}

/**
 * One finished game from the perspective of a single player.
 * `clientGameId` is generated by the client when the game ends and makes recording idempotent.
 */
export interface GameResult {
  clientGameId: string;
  playedAt: number;
  playerCount: number;
  /** 1 = winner */
  placement: number;
  score: number;
  rounds: RoundResult[];
}

const CLIENT_GAME_ID = /^[A-Za-z0-9_-]{8,64}$/;

/** Client generated game ids: URL-safe, 8–64 characters. */
export function isValidClientGameId(value: unknown): value is string {
  return typeof value === 'string' && CLIENT_GAME_ID.test(value);
}

function isInt(value: unknown, min: number, max: number): value is number {
  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
}

function isValidRound(round: unknown): round is RoundResult {
  if (typeof round !== 'object' || round === null) return false;
  const r = round as Record<string, unknown>;
  return (
    isInt(r.bid, 0, ACCOUNT_LIMITS.MAX_ROUNDS_PER_GAME) &&
    isInt(r.tricksWon, 0, ACCOUNT_LIMITS.MAX_ROUNDS_PER_GAME) &&
    isInt(r.roundScore, -10_000, 10_000)
  );
}

/**
 * Structural and plausibility checks. Results are reported by clients, so this guards against
 * malformed data and obviously impossible values, not against a determined cheater.
 */
export function validateGameResult(value: unknown, now: number): GameResult | null {
  if (typeof value !== 'object' || value === null) return null;
  const v = value as Record<string, unknown>;
  if (typeof v.clientGameId !== 'string' || !CLIENT_GAME_ID.test(v.clientGameId)) return null;
  if (!isInt(v.playedAt, 0, now + ACCOUNT_LIMITS.MAX_CLOCK_SKEW_MS)) return null;
  if (!isInt(v.playerCount, ACCOUNT_LIMITS.MIN_PLAYERS, ACCOUNT_LIMITS.MAX_PLAYERS)) return null;
  if (!isInt(v.placement, 1, v.playerCount)) return null;
  if (!isInt(v.score, -100_000, 100_000)) return null;
  if (!Array.isArray(v.rounds) || v.rounds.length > ACCOUNT_LIMITS.MAX_ROUNDS_PER_GAME) return null;
  if (!v.rounds.every(isValidRound)) return null;

  // Round history only contains rounds with a bid, so it need not add up to the final score.
  const rounds = v.rounds.map(({ bid, tricksWon, roundScore }) => ({ bid, tricksWon, roundScore }));

  return {
    clientGameId: v.clientGameId,
    playedAt: v.playedAt,
    playerCount: v.playerCount,
    placement: v.placement,
    score: v.score,
    rounds,
  };
}

export function countCorrectBids(result: Pick<GameResult, 'rounds'>): number {
  return result.rounds.filter((round) => round.bid === round.tricksWon).length;
}

export function countTricksWon(result: Pick<GameResult, 'rounds'>): number {
  return result.rounds.reduce((sum, round) => sum + round.tricksWon, 0);
}
